CREATE DATABASE IF NOT EXISTS healthkey CHARACTER SET utf8mb4;
USE healthkey;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,phone VARCHAR(30),role ENUM('user','admin','superadmin') NOT NULL DEFAULT 'user',is_active TINYINT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE patient_profiles(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,date_of_birth DATE,blood_type VARCHAR(5),allergies TEXT,medical_conditions TEXT,medications TEXT,emergency_contact_name VARCHAR(100),emergency_contact_phone VARCHAR(30),emergency_contact_relationship VARCHAR(50),doctor_name VARCHAR(100),additional_notes TEXT,share_notes TINYINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
-- status: unclaimed (stock tag) -> claimed (owned, profile incomplete) -> active ; disabled by admin
CREATE TABLE qr_codes(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,unique_token CHAR(64) NOT NULL UNIQUE,status ENUM('unclaimed','claimed','active','disabled') DEFAULT 'unclaimed',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE bracelets(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,type VARCHAR(20) NOT NULL DEFAULT 'adult',material VARCHAR(40) NOT NULL DEFAULT 'Silicone',price DECIMAL(8,2) NOT NULL,stock INT NOT NULL DEFAULT 0,color1 CHAR(6) NOT NULL DEFAULT '14B8A6',color2 CHAR(6) NOT NULL DEFAULT '2563EB',description TEXT,is_active TINYINT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(is_active));
CREATE TABLE orders(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,bracelet_id INT NULL,order_number VARCHAR(30) NOT NULL UNIQUE,product_name VARCHAR(100),amount DECIMAL(8,2),payment_method VARCHAR(30),payment_status ENUM('pending','paid','cancelled') DEFAULT 'pending',qr_revealed TINYINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(bracelet_id) REFERENCES bracelets(id) ON DELETE SET NULL);
CREATE TABLE emergency_access_logs(id INT AUTO_INCREMENT PRIMARY KEY,qr_id INT NOT NULL,accessed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,ip_address VARCHAR(45),user_agent VARCHAR(255),FOREIGN KEY(qr_id) REFERENCES qr_codes(id) ON DELETE CASCADE);
CREATE TABLE staff_messages(id INT AUTO_INCREMENT PRIMARY KEY,admin_id INT NOT NULL,sender_role ENUM('super','admin') NOT NULL,message TEXT NOT NULL,is_read TINYINT NOT NULL DEFAULT 0,read_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(admin_id,sender_role,is_read),FOREIGN KEY(admin_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE chat_messages(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,sender ENUM('user','bot','admin') NOT NULL,channel ENUM('ai','admin') NOT NULL DEFAULT 'ai',message TEXT NOT NULL,is_read TINYINT NOT NULL DEFAULT 1,read_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,channel),INDEX(channel,is_read),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS appointments(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(120) NOT NULL,doctor_name VARCHAR(100),location VARCHAR(150),appointment_date DATETIME NOT NULL,notes TEXT,status ENUM('upcoming','completed','cancelled') NOT NULL DEFAULT 'upcoming',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(user_id,appointment_date),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);

